"""Readables and source-bound metadata corrections for sealed I diagnostics."""
import argparse,collections,json,sys
from pathlib import Path
sys.path.insert(0,str(Path(__file__).resolve().parents[1]))
from nfl_v2.shared_subgroups import sha,now,write
from tools.numerical_championship import csvwrite

CONTROLS=('SAVED_RAW_PROJECTION_DIRECTION_RETAINED_PRECISION','SAVED_ADJUSTED_POINT_DIRECTION_RETAINED_PRECISION')

def label(proc):
    if proc==CONTROLS[0]:return 'Saved raw point (retained precision)'
    if proc==CONTROLS[1]:return 'Saved adjusted point (retained precision)'
    names={'hgb-direct-history-controls-v1:absolute_error_point':'HGB direct L1 v1','hgb-direct-history-controls-v1:squared_error_mean':'HGB direct L2 v1','empirical-player-history-control-v1':'Empirical v1','v2-qualified-position-defense-information-wave-v1:D1':'D1 Leaf-CDF v1','v2-qualified-position-defense-information-wave-v1:D2':'D2 Leaf-CDF v1','v2-distribution-controls-reconstruction-v2:ordered_leaf_cdf':'Leaf-CDF v2','v2-distribution-controls-reconstruction-v2:regularized_glm_law':'GLM law v2','v2-c02-explicit-lag-block-removal-leaf-cdf-v1':'C02 Leaf-CDF v1'}
    strict=':strict-current-inputs' in proc
    return names.get(proc.replace(':strict-current-inputs',''),proc)+(' [strict-current]' if strict else '')

def main(a):
    out=a.output;score=out/'SCORES.json';digest=sha(score);scores=json.loads(score.read_bytes());by={r['record_id']:r for r in scores};point={r['record_id']:r for r in scores if r['record_kind']=='forecast_evaluation_view'}
    contexts=json.loads((out/'CONTEXT_TO_DEDUPLICATED_SCORE.json').read_bytes());pairs=json.loads((out/'PAIRED_MAE_COMPARISONS.json').read_bytes());population=json.loads((out/'POPULATION_COMPARISON_BINDINGS.json').read_bytes());annotations=[]
    for index,r in enumerate(scores):
        if r['procedure_id'] in CONTROLS:vintage='SERVER_RETAINED_SAVED_PRECISION_POINT_AND_THRESHOLD;CURRENT_VINTAGE_QUALIFIED_LABELS;INTERNAL_MODEL_VINTAGE_UNVERIFIED;RETROSPECTIVE_P1_REPLAY'
        elif r['record_kind']=='forecast_evaluation_view' and r['horizon_id'].startswith('SAME_SAVED_KICKOFF'):vintage='CURRENT_VINTAGE_FOOTBALL_RECONSTRUCTION;SAVED_KICKOFF_VECTOR_POPULATION_DIAGNOSTIC;NOT_ORIGINAL_ISSUANCE'
        else:vintage='QUALIFIED_SERVER_RETAINED_THRESHOLD_CONTEXT;CURRENT_VINTAGE_7DAY_FOOTBALL_KNOWN_TARGET_TIME_RECONSTRUCTION;NOT_ORIGINAL_ISSUANCE'
        annotations.append(dict(source_row_index=index,record_id=r['record_id'],record_kind=r['record_kind'],original_source_vintage=r.get('source_vintage'),source_vintage=vintage,correction_kind='SOURCE_VINTAGE_METADATA_ONLY'))
    annpath=out/'CURRENT_REPORTING_ANNOTATIONS_I_V1.json'
    if not a.readable_only:write(annpath,dict(schema='v2-I-source-bound-record-vintage-reporting-annotation-v1',source_artifact=score.relative_to(a.root).as_posix(),source_score_sha256=digest,rows=annotations,original_side_labels_corrected=sum(r['record_kind']=='prop_selection_evaluation' for r in annotations),point_missing_metadata_added=sum(r['record_kind']=='forecast_evaluation_view' for r in annotations),new_scores=0,new_predictions=0))
    coverage=[]
    for c in contexts:
        r=point[c['record_id']];conditional=c['context'].startswith('FOCAL_COMMON');outer=r['forecast_rows'] if conditional else r['outer_opportunities']
        coverage.append(dict(**c,target=r['target'],procedure_id=r['procedure_id'],history_regime=r['history_regime'],product_id=r['product_id'],context_outer_opportunities=outer,available_point_forecasts=r['forecast_rows'],context_coverage=r['forecast_rows']/outer if outer else None,canonical_record_outer_opportunities=r['outer_opportunities'],interpretation='Identical recipe/point mask reuses a canonical score; full-source coverage remains in that record, conditional context denominator is reported separately. No missing forecast is imputed.'))
    if not a.readable_only:write(out/'CONTEXT_COVERAGE_EXTENSION_V1.json',coverage)
    sideindex={(r['target'],r['procedure_id'],r['history_regime'],r['product_id'],r['membership_sha256'],r['side']):r for r in scores if r['record_kind']=='prop_selection_evaluation'}
    common=[];own={}
    for c in contexts:
        r=point[c['record_id']];k=(r['target'],r['procedure_id'],r['history_regime'],r['product_id'])
        if c['context']=='OWN_DECISION_ELIGIBLE_FULL_SYSTEM':own[k]=r
        if c['context']=='FOCAL_COMMON_FULL_SYSTEM':common.append(r)
    table=[]
    for r in common:
        k=(r['target'],r['procedure_id'],r['history_regime'],r['product_id']);row={field:r.get(field) for field in('record_id','target','procedure_id','history_regime','product_id','n','mae','mse','rmse','bias','p90_abs','p95_abs','max_abs','fallback_rows','fallback_rate','precision_counts','membership_sha256','forecast_minus_line','actual_minus_line')};row.update(own_supported_n=own[k]['n'],own_forecast_rows=own[k]['forecast_rows'],full_source_outer_offers=own[k]['outer_opportunities'],own_unavailable_forecasts=own[k]['unavailable_forecasts'])
        for side in('over','under','Combined'):
            s=sideindex[*k,r['membership_sha256'],side];m=s['selection_metrics']
            for field,value in dict(selected=s['forecast_rows'],wins=m['WIN'],losses=m['LOSS'],decided=m['denominators']['decided'],hit_rate=m['hit_rate'],status_counts=m['status_counts'],game_uncertainty=m['game_uncertainty']).items():row[side+'_'+field]=value
        table.append(row)
    if not a.readable_only:
        write(out/'MATCHED_FOCAL_SCORECARD.json',table);csvwrite(out/'MATCHED_FOCAL_SCORECARD.csv',table)
        write(out/'DEFAULT_DIAGNOSTIC_VIEW.json',dict(schema='v2-I-source-bound-diagnostic-default-view-v1',canonical_score_source=score.relative_to(a.root).as_posix(),canonical_score_sha256=digest,reporting_annotations=annpath.relative_to(a.root).as_posix(),reporting_annotations_sha256=sha(annpath),context_coverage_extension=(out/'CONTEXT_COVERAGE_EXTENSION_V1.json').relative_to(a.root).as_posix(),point_field='ranking_point in joined retained method grades, prediction only in original model forecast packets',source_original_bytes_unchanged=True,original_source_label_status='189 side labels corrected by annotation;69 point labels added; no metric/forecast/grade correction',new_scores=0))
    lines=['# Why the numerical leaders struggled at the offered lines','','Both focal procedures lose to the retained saved-point controls on identical eligible offers in numerical error as well as selected-side accuracy. This is observed adverse evidence; it is not explained away as an acceptable tradeoff. Neither inverted picks nor a new model was tested. The comparison is to retained raw/adjusted fields, not an authenticated complete current-served overlay track record.','','| Focal procedure | Same-offer n | MAE | Bias(prediction−actual) | Saved raw MAE | Saved adjusted MAE |','|---|---:|---:|---:|---:|---:|']
    focals={'pass_yd':('hgb-direct-history-controls-v1:absolute_error_point','H-MULTI','absolute_error_point'),'pass_cmp':('v2-qualified-position-defense-information-wave-v1:D1','H-MULTI','lower_median')}
    for target,focal in focals.items():
        f=next(r for r in table if (r['target'],r['procedure_id'],r['history_regime'],r['product_id'])==(target,*focal));raw=next(r for r in table if r['target']==target and r['procedure_id']==CONTROLS[0]);adj=next(r for r in table if r['target']==target and r['procedure_id']==CONTROLS[1]);lines.append(f"| {label(focal[0])} / {target} / H-MULTI / {focal[2]} | {f['n']} | {f['mae']:.6f} | {f['bias']:+.6f} | {raw['mae']:.6f} | {adj['mae']:.6f} |")
    lines += ['', 'HGB passing yards has28/80correct directions: Over14/32andUnder14/48. D1 completions has33/76. The shared full source universe contains84offers per target; HGB has80eligible saved points and D1 has76. Missing/unqualified points remain unavailable, not zero predictions or hidden abstentions.', '', 'The primary numerical benchmark covered2026W1–7and a broad retrospective QBparticipant population. The offered panel is the qualified W5–7subset. Within the same42covered games, the original unchanged focal forecasts show:', '', '| Target | Population diagnostic | Supported n | MAE | Bias |', '|---|---|---:|---:|---:|']
    for p in population:
        r=point[p['record_id']];lines.append(f"| {p['target']} | {p['context']} | {r['n']} | {r['mae']:.6f} | {r['bias']:+.6f} |")
    lines += ['', 'Offered-player selection **improves MAE in this same-game diagnostic**, while negative bias increases. Therefore these results do not show that selected players were simply harder to predict. They also do not prove that backups, an L1objective, a role change or a coding defect caused the residual bias. The kickoff population views are separate from the actual earlier-decision reconstruction. On each admitted focal row, the original kickoff saved point and label equal the point and label in the qualified earlier-decision row; no new vector or prediction was computed.', '', 'For HGB passing yards, mean forecast−line is−11.089230yards while mean actual−line is+6.762500, giving bias−17.851730. Median forecast−line is−5.247851and median actual−line+13.000000. For D1 completions, corresponding means are−0.973684and+0.631579, giving bias−1.605263; medians are−0.5and+1.0. This is a measured directional mismatch on the retained panel. It does not identify a remedy or establish profitable opposite picks.', '', '## Every registered comparator on the focal common rows','','The finite roster includes directL1/L2, empirical mean/median, Leaf/C02/D1/D2, GLM, strict-current alternatives, the existing earlier-score selector and saved raw/adjusted fields. Mean/median views share models where appropriate and are not new learners. Different input groups, strict-information policies and point functionals remain named; these are procedure comparisons, not a clean learner-only causal ablation.', '', '| Target | Exact procedure/history/output | Paired n / own n / outer | MAE | Bias | Median forecast−line | Predicted Over W/L/decided; hit rate | Predicted Under W/L/decided; hit rate | Combined W/L/decided; hit rate |','|---|---|---:|---:|---:|---:|---:|---:|']
    for r in table:
        lines.append(f"| {r['target']} | {label(r['procedure_id'])} / {r['history_regime']} / {r['product_id']} | {r['n']}/{r['own_supported_n']}/{r['full_source_outer_offers']} | {r['mae']:.6f} | {r['bias']:+.6f} | {r['forecast_minus_line']['p50']:+.6f} | {r['over_wins']}/{r['over_losses']}/{r['over_decided']}; {('N/A' if r['over_hit_rate'] is None else format(100*r['over_hit_rate'],'.2f')+'%')} | {r['under_wins']}/{r['under_losses']}/{r['under_decided']}; {('N/A' if r['under_hit_rate'] is None else format(100*r['under_hit_rate'],'.2f')+'%')} | {r['Combined_wins']}/{r['Combined_losses']}/{r['Combined_decided']}; {100*r['Combined_hit_rate']:.2f}% |" if r['Combined_hit_rate'] is not None else f"| {r['target']} | {label(r['procedure_id'])} | {r['n']} | N/A | N/A | N/A | N/A | N/A | N/A |")
    lines += ['', 'W/L means wins/losses, not wins/decided; the machine table publishes selected count, decided denominator, hit rate and every status separately. Combined hit rate uses summed wins/(summed wins+losses). Empty buckets are N/A. Means and medians are not silently substituted. Saved controls preserve their retained precision; unavailable internal digits are not invented.', '', '## Matched uncertainty and fallback scope','','| Target | Comparator minus focal MAE | Paired n | Difference | Game-cluster95% sensitivity |','|---|---|---:|---|']
    for p in pairs:
        if p['context']!='FOCAL_COMMON_FULL_SYSTEM' or p['candidate_recipe'][0] not in CONTROLS:continue
        lines.append(f"| {p['target']} | {label(p['candidate_recipe'][0])} minus focal | {p['n']} | {p['delta']:+.6f} | {p['game_normal95_sensitivity']} |")
    lines += ['', 'Negative differences favor the saved comparator. These are exposed, selection-unadjusted paired comparisons; three weeks are insufficient for the registered whole-week interval. Full-system and both-known-learned intersections are retained separately in[all paired comparisons](PAIRED_MAE_COMPARISONS.csv). Saved-point model/fallback metadata is unknown, so their learned-only comparison is not applicable. Sparse and fallback cases are retained in each method’s own full-system score and coverage.', '', 'Identical recipe/mask scores are deduplicated. A common-mask alias can reuse a full-source canonical score because its points/losses are identical; the[context coverage extension](CONTEXT_COVERAGE_EXTENSION_V1.json) supplies the conditional denominator separately. The full-source unavailable count must not disappear when showing a paired overlap.', '', '## Identity, units, chronology and functional audit','','The actual method point is `ranking_point` in retained joined grades and frozen plan `point`. The joined `prediction` field is the saved adjusted-site reference; using it as the model point would be an adapter error. Original forecast packets use their own `prediction` as the model point. Exact game/player/category/line/actual/decision-clock equality is asserted for common comparisons, and saved point-versus-line directions are asserted unchanged. Official signed yards and integer completion actuals are preserved; forecasts and lines are not rounded.', '', 'HGB is a direct absolute-error point fit. D1 lower median is extracted from squared-error forest response partitions plus the registered5%prior; it is not a direct absolute-loss model. The original feature rules, training eligibility, query cutoffs, fallback and seven-day source assumption remain unchanged. Current-vintage football reconstruction is not authenticated historical source publication; original server-retained thresholds/context do not authenticate original V2issuance.', '', 'The shared side aggregator inherited an overly broad original-point source label. The[bound metadata correction](CURRENT_REPORTING_ANNOTATIONS_I_V1.json) corrects189side labels and supplies69missing point labels without changing a canonical score, point, side or outcome. The[default diagnostic view](DEFAULT_DIAGNOSTIC_VIEW.json) requires that correction. Raw/adjusted saved references and reconstructed V2points retain distinct evidence tiers.', '', 'Worked win/loss cases for both selected sides are retained privately with original stable identity, point, line, actual, grade and clock/source references. They were chosen by the preregistered first chronological case per bucket for explanation only. No raw player/offer row or private locator is published. The92,891-byte derivative is retained in the isolated private workspace with its hash; no new upload/restoration receipt is claimed. Its pinned parent rows and deterministic source support reconstruction. Any approved companion-store restoration must be recorded separately.', '', '## Next supported action','','The evidence supports investigating current role/opportunity information, source freshness and point-functional/population specialization on unchanged comparable rows; it does not establish which mechanism will repair these losses. Any changed prediction, calibration, role routing or inverted selection needs a separately registered earlier-chosen procedure and later evaluation. Current production and original forecasts remain unchanged. Missing exact historical cells and recovery gates remain separate; no new fit or capture was admitted by this diagnostic.', '', '[Complete machine scorecard](MATCHED_FOCAL_SCORECARD.csv) · [Canonical scores](SCORES.json) · [Frozen roster/masks](FROZEN_PROTOCOL.json) · [Execution receipt](RUN_RECEIPT.json) · [Population bindings](POPULATION_COMPARISON_BINDINGS.json).']
    text='\n'.join(lines)+'\n'
    for old,new in [('covered2026','covered 2026'),('2026W1','2026 W1'),('W5–7subset','W5–7 subset'),('same42','same 42'),('contains84','contains 84'),('has80','has 80'),('has76','has 76'),('L1objective','L1 objective'),('D1completions','D1 completions'),('side labels','side labels')]:text=text.replace(old,new)
    (out/'README.md').write_text(text)
